1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"encoding/json"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"math"
11		"os"
12		"path/filepath"
13		"sort"
14		"strconv"
15	)
16	
17	// On-disk format (queue.log):
18	//
19	//	magic   = "RELAYPROOF-QUEUE-V1\n"
20	//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
21	//
22	// The log is an append-only write-ahead log. Every mutating operation is
23	// persisted as one framed, checksummed record and fsynced before it is
24	// acknowledged; a success record frames the local success entry and the nonce
25	// consumption together, so the two can never take effect separately.
26	//
27	// A success (result or compacted state) names the consumed triple in three
28	// independent fields, consumeFrom/consumeTo/consumeNonce, alongside consumeBy.
29	// Chain names are stored verbatim as raw UTF-8 — they may contain ':' or even
30	// U+0000 — so the triple is never flattened into one delimiter-joined string,
31	// which would let distinct routing paths share one consumption identity.
32	//
33	// Crash recovery: a frame missing bytes at end of file, or a final frame with
34	// a bad checksum, is the torn tail of a write that was never acknowledged and
35	// is truncated. That recovery is only available once the log's leading
36	// version record has itself been read whole and verified: the magic alone
37	// never establishes a usable version, so a log whose very first record is
38	// partial (only some length bytes, or the length without the body and CRC),
39	// complete but checksum-bad, not a version record, or names an unsupported
40	// version is rejected wholesale with ErrCorrupt and left byte-for-byte
41	// untouched — it can never be truncated down to an empty-looking log that a
42	// later append would turn into a headerless one. Bad checksums or framing
43	// anywhere before the end, a foreign header, or an unsupported version
44	// likewise reject the directory with ErrCorrupt; state is never silently
45	// cleared.
46	//
47	// Logs written by older builds recorded the consumption as one NUL-joined
48	// consumeKey string. Such success entries are still accepted on replay: the
49	// key is validated against the record's own (from,to,nonce) and consumeBy,
50	// and only the record's own triple is marked consumed. A legacy key that does
51	// not match the record it is attached to — a genuinely inconsistent old
52	// record — rejects the whole directory with ErrCorrupt instead of silently
53	// accepting or "repairing" the bad entry.
54	
55	const (
56		logName          = "queue.log"
57		logMagic         = "RELAYPROOF-QUEUE-V1\n"
58		compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
59		compactFileMode  = 0o600
60		frameHeaderSize  = 4
61		frameCRCsSize    = 4
62	)
63	
64	var crcTable = crc32.MakeTable(crc32.IEEE)
65	
66	// JSON log entry kinds.
67	const (
68		kindVersion = "version"
69		kindSource  = "source"
70		kindHeader  = "header"
71		kindSubmit  = "submit"
72		kindResult  = "result"
73		kindState   = "state" // compacted snapshot: full status after >=1 attempts
74		kindAdvance = "advance"
75		currentLogV = 1
76	)
77	
78	type logEntry struct {
79		T string `json:"t"`
80		V int    `json:"v,omitempty"`
81	
82		Chain   string `json:"chain,omitempty"`
83		Height  int64  `json:"height,omitempty"`
84		Root    string `json:"root,omitempty"`
85		Trusted bool   `json:"trusted,omitempty"`
86	
87		Seq       int64  `json:"seq,omitempty"`
88		ID        string `json:"id,omitempty"`
89		From      string `json:"from,omitempty"`
90		To        string `json:"to,omitempty"`
91		Nonce     uint64 `json:"nonce,omitempty"`
92		Payload   string `json:"payload,omitempty"`
93		ProofAt   int64  `json:"proofAt,omitempty"`
94		ExpiresAt int64  `json:"expiresAt,omitempty"`
95	
96		Now       int64  `json:"now,omitempty"`
97		Status    string `json:"status,omitempty"`
98		Reason    string `json:"reason,omitempty"`
99		Attempts  int    `json:"attempts,omitempty"`
100		NextRetry int64  `json:"nextRetry,omitempty"`
101	
102		// Consumed triple of a success entry, stored as three independent values
103		// so routing paths that share a flattened key stay distinct. consumeBy is
104		// the id of the successful message.
105		ConsumeFrom  string `json:"consumeFrom,omitempty"`
106		ConsumeTo    string `json:"consumeTo,omitempty"`
107		ConsumeNonce uint64 `json:"consumeNonce,omitempty"`
108		ConsumeBy    string `json:"consumeBy,omitempty"`
109	
110		// ConsumeKey is the legacy (pre-triple) NUL-joined consumption string. It
111		// is accepted only while replaying logs written by older builds and is
112		// never written anymore.
113		ConsumeKey string `json:"consumeKey,omitempty"`
114	}
115	
116	// legacyNonceKey reproduces the consumption string used by older builds:
117	// from NUL to NUL nonce. It exists solely to validate records in pre-existing
118	// state directories; new state always uses consumeToken triples.
119	func legacyNonceKey(from, to string, nonce uint64) string {
120		return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
121	}
122	
123	type store struct {
124		dir  string
125		f    *os.File
126		size int64
127		// snap, when set, supplies a live-state snapshot for log compaction.
128		snap func() *loadedState
129		// injectErr is a test hook forcing append to fail after opening the file.
130		injectErr error
131	}
132	
133	// loadedState is the fully replayed (or live) queue state.
134	type loadedState struct {
135		sources  map[string]bool
136		headers  map[string]*headerState
137		records  map[string]*Record
138		consumed map[consumeToken]string
139		nextSeq  int64
140		now      int64
141	}
142	
143	func openStore(dir string) (*store, *loadedState, error) {
144		path := filepath.Join(dir, logName)
145	
146		if _, err := os.Stat(path); err != nil {
147			if !os.IsNotExist(err) {
148				return nil, nil, fmt.Errorf("stat %s: %w", logName, err)
149			}
150			if err := createLog(path, dir); err != nil {
151				return nil, nil, err
152			}
153		} else if err := checkMagic(path); err != nil {
154			return nil, nil, err
155		}
156	
157		raw, err := os.ReadFile(path)
158		if err != nil {
159			return nil, nil, fmt.Errorf("read %s: %w", logName, err)
160		}
161		goodLen, state, err := replayLog(raw)
162		if err != nil {
163			return nil, nil, err
164		}
165		if int64(len(raw)) != goodLen {
166			// Drop the torn tail of an entry that can never have been acknowledged.
167			tf, err := os.OpenFile(path, os.O_RDWR, compactFileMode)
168			if err != nil {
169				return nil, nil, fmt.Errorf("open %s for repair: %w", logName, err)
170			}
171			if err := tf.Truncate(goodLen); err != nil {
172				tf.Close()
173				return nil, nil, fmt.Errorf("truncate torn log tail: %w", err)
174			}
175			if err := tf.Sync(); err != nil {
176				tf.Close()
177				return nil, nil, fmt.Errorf("sync repaired %s: %w", logName, err)
178			}
179			if err := tf.Close(); err != nil {
180				return nil, nil, err
181			}
182			if err := syncDir(dir); err != nil {
183				return nil, nil, err
184			}
185		}
186	
187		f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, compactFileMode)
188		if err != nil {
189			return nil, nil, fmt.Errorf("open %s for append: %w", logName, err)
190		}
191		if _, err := f.Seek(0, io.SeekEnd); err != nil {
192			f.Close()
193			return nil, nil, err
194		}
195		return &store{dir: dir, f: f, size: goodLen}, state, nil
196	}
197	
198	func createLog(path, dir string) error {
199		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
200		if err != nil {
201			return fmt.Errorf("create %s: %w", logName, err)
202		}
203		frame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))
204		if _, err := f.Write(append([]byte(logMagic), frame...)); err != nil {
205			f.Close()
206			return fmt.Errorf("write %s header: %w", logName, err)
207		}
208		if err := f.Sync(); err != nil {
209			f.Close()
210			return fmt.Errorf("sync %s: %w", logName, err)
211		}
212		if err := f.Close(); err != nil {
213			return err
214		}
215		return syncDir(dir)
216	}
217	
218	func mustMarshal(e *logEntry) []byte {
219		b, err := json.Marshal(e)
220		if err != nil {
221			panic(err)
222		}
223		return b
224	}
225	
226	// encodeFrame wraps a payload with its big-endian length and CRC32.
227	func encodeFrame(payload []byte) []byte {
228		frame := make([]byte, 0, frameHeaderSize+len(payload)+frameCRCsSize)
229		var hdr [4]byte
230		binary.BigEndian.PutUint32(hdr[:], uint32(len(payload)))
231		frame = append(frame, hdr[:]...)
232		frame = append(frame, payload...)
233		var crc [4]byte
234		binary.BigEndian.PutUint32(crc[:], crc32.Checksum(payload, crcTable))
235		frame = append(frame, crc[:]...)
236		return frame
237	}
238	
239	func checkMagic(path string) error {
240		f, err := os.Open(path)
241		if err != nil {
242			return fmt.Errorf("open %s: %w", logName, err)
243		}
244		defer f.Close()
245		buf := make([]byte, len(logMagic))
246		n, err := io.ReadFull(f, buf)
247		if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
248			return fmt.Errorf("read %s header: %w", logName, err)
249		}
250		if n < len(logMagic) || !bytes.Equal(buf, []byte(logMagic)) {
251			return fmt.Errorf("%w: missing or foreign %s header", ErrCorrupt, logName)
252		}
253		return nil
254	}
255	
256	// replayLog parses and validates the log, returning the byte length of the
257	// longest intact prefix and the reconstructed state.
258	func replayLog(raw []byte) (int64, *loadedState, error) {
259		if !bytes.HasPrefix(raw, []byte(logMagic)) {
260			return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
261		}
262		state := &loadedState{
263			sources:  map[string]bool{},
264			headers:  map[string]*headerState{},
265			records:  map[string]*Record{},
266			consumed: map[consumeToken]string{},
267		}
268	
269		// The leading version record is the precondition for every later recovery
270		// decision: nothing after the magic can be replayed or treated as a
271		// truncatable tail until it has been read complete, checksummed and
272		// confirmed to be a supported version. Validate it on its own so a torn or
273		// bad first record can never look like an empty log that is safe to append
274		// to.
275		verEnd, err := readVersionRecord(raw, len(logMagic))
276		if err != nil {
277			return 0, nil, err
278		}
279		pos := verEnd
280	
281		for pos < len(raw) {
282			// Need at least the length header.
283			if len(raw)-pos < frameHeaderSize {
284				return int64(pos), state, nil // torn length header of an unacked write
285			}
286			n := int(binary.BigEndian.Uint32(raw[pos : pos+frameHeaderSize]))
287			if n == 0 {
288				return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
289			}
290			bodyStart := pos + frameHeaderSize
291			frameEnd := bodyStart + n + frameCRCsSize
292			if frameEnd > len(raw) {
293				return int64(pos), state, nil // torn body/CRC of an unacked write
294			}
295			payload := raw[bodyStart : bodyStart+n]
296			wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
297			if crc32.Checksum(payload, crcTable) != wantCRC {
298				if frameEnd == len(raw) {
299					// Torn sectors of the final, unacknowledged frame.
300					return int64(pos), state, nil
301				}
302				return 0, nil, fmt.Errorf("%w: checksum mismatch at offset %d", ErrCorrupt, pos)
303			}
304			var e logEntry
305			if err := json.Unmarshal(payload, &e); err != nil {
306				return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
307			}
308			if e.T == kindVersion {
309				return 0, nil, fmt.Errorf("%w: unexpected version record at offset %d", ErrCorrupt, pos)
310			}
311			if err := applyEntry(state, &e); err != nil {
312				return 0, nil, err
313			}
314			pos = frameEnd
315		}
316		return int64(pos), state, nil
317	}
318	
319	// readVersionRecord reads and validates the log's first record at offset
320	// start, returning the offset just past it. A correct magic prefix alone is
321	// not a valid log: the version record must be fully present, its checksum
322	// must match, and it must name a supported version. Every other shape — a
323	// record cut short at end of file (one to three length bytes, or the length
324	// without the body and CRC), a complete final record with a bad checksum,
325	// invalid JSON, a non-version record, or an unsupported version — is a
326	// corrupt log, never a truncatable tail.
327	func readVersionRecord(raw []byte, start int) (int, error) {
328		if len(raw)-start < frameHeaderSize {
329			return 0, fmt.Errorf("%w: incomplete version record: only %d of %d length bytes after header",
330				ErrCorrupt, len(raw)-start, frameHeaderSize)
331		}
332		n := int(binary.BigEndian.Uint32(raw[start : start+frameHeaderSize]))
333		if n == 0 {
334			return 0, fmt.Errorf("%w: zero-length version record at offset %d", ErrCorrupt, start)
335		}
336		bodyStart := start + frameHeaderSize
337		frameEnd := bodyStart + n + frameCRCsSize
338		if frameEnd > len(raw) {
339			return 0, fmt.Errorf("%w: incomplete version record: length %d but only %d body/checksum bytes present",
340				ErrCorrupt, n, len(raw)-bodyStart)
341		}
342		payload := raw[bodyStart : bodyStart+n]
343		wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
344		if crc32.Checksum(payload, crcTable) != wantCRC {
345			return 0, fmt.Errorf("%w: checksum mismatch in version record at offset %d", ErrCorrupt, start)
346		}
347		var e logEntry
348		if err := json.Unmarshal(payload, &e); err != nil {
349			return 0, fmt.Errorf("%w: invalid version record at offset %d: %v", ErrCorrupt, start, err)
350		}
351		if e.T != kindVersion {
352			return 0, fmt.Errorf("%w: first record is %q, not a version record", ErrCorrupt, e.T)
353		}
354		if e.V != currentLogV {
355			return 0, fmt.Errorf("%w: unsupported log version %d", ErrCorrupt, e.V)
356		}
357		return frameEnd, nil
358	}
359	
360	// entryCarriesConsumption reports whether a non-success entry smuggles any
361	// consumption field, which is always corrupt.
362	func entryCarriesConsumption(e *logEntry) bool {
363		return e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0 ||
364			e.ConsumeKey != "" || e.ConsumeBy != ""
365	}
366	
367	// acceptConsumption validates the triple consumed by a success result or
368	// compacted state entry and records it in s.consumed. The triple must
369	// identify the record's own message and be consumed by that message.
370	//
371	// Logs written by older builds carry the consumption as one NUL-joined
372	// consumeKey. Such an entry is accepted only when that legacy key matches the
373	// record's own triple; it is the record's own triple that is marked consumed,
374	// never the ambiguous flattened string — so two distinct paths that happened
375	// to share one old flattened key each consume only themselves. A legacy key
376	// that does not match its record is an inconsistent record and rejected.
377	func acceptConsumption(s *loadedState, rec *Record, e *logEntry, corrupt func(string, ...any) error) (consumeToken, error) {
378		m := rec.Msg.Message
379		if e.ConsumeBy != e.ID {
380			return consumeToken{}, corrupt("success entry for %q is marked consumed by %q", e.ID, e.ConsumeBy)
381		}
382		token := newConsumeToken(m.From, m.To, m.Nonce)
383		hasTriple := e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0
384		switch {
385		case hasTriple:
386			if e.ConsumeKey != "" {
387				return consumeToken{}, corrupt("success entry for %q carries both a triple and a legacy consume key", e.ID)
388			}
389			if e.ConsumeFrom != m.From || e.ConsumeTo != m.To || e.ConsumeNonce != m.Nonce {
390				return consumeToken{}, corrupt("success entry for %q carries mismatched nonce consumption: %q -> %q nonce %d", e.ID, e.ConsumeFrom, e.ConsumeTo, e.ConsumeNonce)
391			}
392		case e.ConsumeKey != "":
393			if want := legacyNonceKey(m.From, m.To, m.Nonce); e.ConsumeKey != want {
394				return consumeToken{}, corrupt("success entry for %q carries a legacy consume key for a different path", e.ID)
395			}
396		default:
397			return consumeToken{}, corrupt("success entry for %q carries no nonce consumption", e.ID)
398		}
399		if winner, taken := s.consumed[token]; taken {
400			return consumeToken{}, corrupt("nonce %s already consumed by %q while accepting %q", token, winner, e.ID)
401		}
402		s.consumed[token] = e.ID
403		return token, nil
404	}
405	
406	func applyEntry(s *loadedState, e *logEntry) error {
407		corrupt := func(msg string, args ...any) error {
408			return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
409		}
410		switch e.T {
411		case kindSource:
412			if e.Chain == "" {
413				return corrupt("source entry with empty chain")
414			}
415			s.sources[e.Chain] = true
416		case kindHeader:
417			if e.Chain == "" || e.Height < 0 {
418				return corrupt("bad header entry: %+v", e)
419			}
420			// Replay is permissive: historical same-height coverage is never
421			// rejected as a conflict, and recovery relies only on the header
422			// records actually kept in the log. The latest header is the last one
423			// written; the highest trusted header is the max-height trusted one,
424			// with ties going to the later write (matching old overwrite
425			// semantics). Neither is fabricated from lost history.
426			hs := s.headers[e.Chain]
427			if hs == nil {
428				hs = &headerState{}
429				s.headers[e.Chain] = hs
430			}
431			hs.latest = Header{Chain: e.Chain, Height: e.Height, Root: e.Root, Trusted: e.Trusted}
432			if e.Trusted && (hs.trusted == nil || e.Height >= hs.trusted.Height) {
433				t := hs.latest
434				hs.trusted = &t
435			}
436		case kindSubmit:
437			if e.ID == "" || e.From == "" || e.To == "" || e.ProofAt < 0 || e.ExpiresAt < 0 {
438				return corrupt("bad submit entry: %+v", e)
439			}
440			if _, dup := s.records[e.ID]; dup {
441				return corrupt("duplicate submit for id %q", e.ID)
442			}
443			if e.Seq != s.nextSeq {
444				return corrupt("submit seq %d out of order, expected %d", e.Seq, s.nextSeq)
445			}
446			s.records[e.ID] = &Record{
447				Msg: Envelope{
448					Message: Message{
449						ID:      e.ID,
450						From:    e.From,
451						To:      e.To,
452						Nonce:   e.Nonce,
453						Payload: e.Payload,
454						ProofAt: e.ProofAt,
455					},
456					ExpiresAt: e.ExpiresAt,
457				},
458				Status: StatusPending,
459				Reason: "awaiting first processing",
460				Seq:    e.Seq,
461			}
462			s.nextSeq++
463		case kindResult:
464			rec, ok := s.records[e.ID]
465			if !ok {
466				return corrupt("result for unknown id %q", e.ID)
467			}
468			if isTerminal(rec.Status) {
469				return corrupt("result for terminal id %q", e.ID)
470			}
471			if rec.Attempts > 0 && e.Now < rec.LastProcAt {
472				return corrupt("result time %d before prior time %d for %q", e.Now, rec.LastProcAt, e.ID)
473			}
474			if e.Attempts != rec.Attempts+1 {
475				return corrupt("attempts jump %d -> %d for %q", rec.Attempts, e.Attempts, e.ID)
476			}
477			if !validStatus(e.Status) || e.Status == StatusPending {
478				return corrupt("bad result status %q for %q", e.Status, e.ID)
479			}
480			switch e.Status {
481			case StatusWaiting:
482				scheduled, ok := validWaitingSchedule(e.Now, e.Attempts, e.NextRetry)
483				if !ok {
484					return corrupt("waiting result has wrong retry schedule for %q", e.ID)
485				}
486				// Repair a legacy overflowed (negative) retry to the ceiling in
487				// memory; the next compaction writes the repaired value back.
488				e.NextRetry = scheduled
489				if entryCarriesConsumption(e) {
490					return corrupt("waiting result for %q carries nonce consumption fields", e.ID)
491				}
492			case StatusSuccess:
493				if e.NextRetry != 0 {
494					return corrupt("success entry for %q carries retry time", e.ID)
495				}
496				if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
497					return err
498				}
499			default: // terminal failure kinds
500				if e.NextRetry != 0 || entryCarriesConsumption(e) {
501					return corrupt("terminal entry for %q carries scheduling/consume fields", e.ID)
502				}
503			}
504			rec.Attempts = e.Attempts
505			rec.LastProcAt = e.Now
506			rec.Status = e.Status
507			rec.Reason = e.Reason
508			rec.NextRetry = e.NextRetry
509			if e.Now > s.now {
510				s.now = e.Now
511			}
512		case kindState:
513			// Compacted snapshot: the message already has >=1 attempts and the
514			// entry carries its full current status, so there is no attempts-jump
515			// invariant to check against prior result entries (there are none).
516			rec, ok := s.records[e.ID]
517			if !ok {
518				return corrupt("state for unknown id %q", e.ID)
519			}
520			if rec.Attempts != 0 {
521				return corrupt("duplicate state for id %q", e.ID)
522			}
523			if !validStatus(e.Status) || e.Status == StatusPending {
524				return corrupt("bad state status %q for %q", e.Status, e.ID)
525			}
526			if e.Attempts < 1 {
527				return corrupt("state with zero attempts for %q", e.ID)
528			}
529			switch e.Status {
530			case StatusWaiting:
531				scheduled, ok := validWaitingSchedule(e.Now, e.Attempts, e.NextRetry)
532				if !ok {
533					return corrupt("waiting state has wrong retry schedule for %q", e.ID)
534				}
535				e.NextRetry = scheduled
536				if entryCarriesConsumption(e) {
537					return corrupt("waiting state for %q carries nonce consumption fields", e.ID)
538				}
539			case StatusSuccess:
540				if e.NextRetry != 0 {
541					return corrupt("success state for %q carries retry time", e.ID)
542				}
543				if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
544					return err
545				}
546			default:
547				if e.NextRetry != 0 || entryCarriesConsumption(e) {
548					return corrupt("terminal state for %q carries scheduling/consume fields", e.ID)
549				}
550			}
551			rec.Attempts = e.Attempts
552			rec.LastProcAt = e.Now
553			rec.Status = e.Status
554			rec.Reason = e.Reason
555			rec.NextRetry = e.NextRetry
556			if e.Now > s.now {
557				s.now = e.Now
558			}
559		case kindAdvance:
560			if e.Now < s.now {
561				return corrupt("advance checkpoint %d before known time %d", e.Now, s.now)
562			}
563			s.now = e.Now
564		default:
565			return corrupt("unknown record type %q", e.T)
566		}
567		return nil
568	}
569	
570	func validStatus(s string) bool {
571		switch s {
572		case StatusPending, StatusWaiting, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
573			return true
574		}
575		return false
576	}
577	
578	// validWaitingSchedule validates the retry instant recorded on a waiting
579	// result or compacted-state entry against the processing time and attempt
580	// number. The canonical schedule is nextRetryAt(now, attempts): now plus the
581	// backoff delay, saturated at math.MaxInt64 when it would overflow.
582	//
583	// Logs written by older builds contain the raw now+delay even near the
584	// ceiling, where the addition wrapped around to a value below now (typically
585	// negative). That exact wrapped value is the only non-canonical schedule
586	// accepted: it proves the entry came from the old scheduler rather than from
587	// arbitrary corruption, and it is repaired in memory to the saturated
588	// ceiling, which the next compaction persists. Any other retry time — zero,
589	// an arbitrary instant, or a value before the processing time that is not the
590	// exact legacy overflow — is rejected as corrupt.
591	func validWaitingSchedule(now int64, attempts int, stored int64) (int64, bool) {
592		canonical := nextRetryAt(now, attempts)
593		if stored == canonical {
594			return stored, true
595		}
596		wrapped := now + nextRetryDelay(attempts)
597		if wrapped < now && stored == wrapped {
598			return math.MaxInt64, true
599		}
600		return 0, false
601	}
602	
603	func (s *store) close() error {
604		if s.f == nil {
605			return nil
606		}
607		err := s.f.Sync()
608		cerr := s.f.Close()
609		s.f = nil
610		if err != nil {
611			return err
612		}
613		return cerr
614	}
615	
616	// forceClose releases the file without the final sync after a failed write.
617	func (s *store) forceClose() {
618		if s.f == nil {
619			return
620		}
621		s.f.Close()
622		s.f = nil
623	}
624	
625	// append writes one framed, checksummed, fsynced record.
626	func (s *store) append(e *logEntry) error {
627		if s.injectErr != nil {
628			return s.injectErr
629		}
630		body, err := json.Marshal(e)
631		if err != nil {
632			return fmt.Errorf("encode log entry: %w", err)
633		}
634		if _, err := s.f.Write(encodeFrame(body)); err != nil {
635			return fmt.Errorf("write %s: %w", logName, err)
636		}
637		if err := s.f.Sync(); err != nil {
638			return fmt.Errorf("sync %s: %w", logName, err)
639		}
640		if info, err := s.f.Stat(); err == nil {
641			s.size = info.Size()
642		} else {
643			s.size += int64(frameHeaderSize + len(body) + frameCRCsSize)
644		}
645		return nil
646	}
647	
648	// needsCompaction reports whether the log crossed the compaction threshold.
649	func (s *store) needsCompaction() bool {
650		return s.size > compactThreshold && s.snap != nil
651	}
652	
653	func (s *store) appendRegisterSource(chain string) error {
654		return s.append(&logEntry{T: kindSource, Chain: chain})
655	}
656	
657	func (s *store) appendHeader(h Header) error {
658		return s.append(&logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
659	}
660	
661	func (s *store) appendSubmit(rec *Record) error {
662		m := rec.Msg.Message
663		return s.append(&logEntry{
664			T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
665			Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
666		})
667	}
668	
669	// appendResult records one processing outcome. On success the consumed triple
670	// (consumeFrom/consumeTo/consumeNonce) and its consumer are part of the same
671	// durable record, committing together atomically. token is nil for every
672	// non-success status.
673	func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, token *consumeToken, consumeBy string) error {
674		e := &logEntry{
675			T: kindResult, Now: now, ID: rec.Msg.Message.ID,
676			Status: status, Reason: reason, Attempts: attempts,
677		}
678		if status == StatusSuccess {
679			if token == nil || consumeBy == "" {
680				return fmt.Errorf("internal error: success result for %q missing nonce consumption", rec.Msg.Message.ID)
681			}
682			e.ConsumeFrom = token.from
683			e.ConsumeTo = token.to
684			e.ConsumeNonce = token.nonce
685			e.ConsumeBy = consumeBy
686		}
687		return s.append(e)
688	}
689	
690	// appendWaiting records a waiting outcome with a retry instant the queue
691	// layer already computed and saturated, so the log never carries an overflowed
692	// negative schedule.
693	func (s *store) appendWaiting(now int64, rec *Record, reason string, attempts int, nextRetry int64) error {
694		return s.append(&logEntry{
695			T: kindResult, Now: now, ID: rec.Msg.Message.ID,
696			Status: StatusWaiting, Reason: reason, Attempts: attempts, NextRetry: nextRetry,
697		})
698	}
699	
700	func (s *store) appendAdvance(now int64) error {
701		return s.append(&logEntry{T: kindAdvance, Now: now})
702	}
703	
704	// compact atomically replaces the log with a deterministic snapshot of live
705	// state. It must run while Queue.mu is held (no concurrent mutation), and only
706	// after in-memory state reflects every acknowledged append.
707	func (s *store) compact(state *loadedState) error {
708		entries := []*logEntry{{T: kindVersion, V: currentLogV}}
709	
710		chains := make([]string, 0, len(state.sources))
711		for c := range state.sources {
712			chains = append(chains, c)
713		}
714		sort.Strings(chains)
715		for _, c := range chains {
716			entries = append(entries, &logEntry{T: kindSource, Chain: c})
717		}
718	
719		headerChains := make([]string, 0, len(state.headers))
720		for c := range state.headers {
721			headerChains = append(headerChains, c)
722		}
723		sort.Strings(headerChains)
724		for _, c := range headerChains {
725			hs := state.headers[c]
726			// Write the highest trusted header first, then the latest header when
727			// it differs. Replay reconstructs latest as the last entry and the
728			// highest trusted as the max-height trusted entry, so this order
729			// restores both exactly.
730			if hs.trusted != nil {
731				entries = append(entries, &logEntry{T: kindHeader, Chain: hs.trusted.Chain, Height: hs.trusted.Height, Root: hs.trusted.Root, Trusted: hs.trusted.Trusted})
732			}
733			if hs.trusted == nil || hs.latest != *hs.trusted {
734				entries = append(entries, &logEntry{T: kindHeader, Chain: hs.latest.Chain, Height: hs.latest.Height, Root: hs.latest.Root, Trusted: hs.latest.Trusted})
735			}
736		}
737	
738		seqs := make([]int64, 0, len(state.records))
739		bySeq := make(map[int64]*Record, len(state.records))
740		for _, rec := range state.records {
741			seqs = append(seqs, rec.Seq)
742			bySeq[rec.Seq] = rec
743		}
744		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
745		for _, seq := range seqs {
746			rec := bySeq[seq]
747			m := rec.Msg.Message
748			entries = append(entries, &logEntry{
749				T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
750				Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
751			})
752			if rec.Attempts > 0 {
753				re := &logEntry{
754					T: kindState, Now: rec.LastProcAt, ID: m.ID,
755					Status: rec.Status, Reason: rec.Reason, Attempts: rec.Attempts,
756				}
757				if rec.Status == StatusWaiting {
758					re.NextRetry = rec.NextRetry
759				}
760				if rec.Status == StatusSuccess {
761					re.ConsumeFrom = m.From
762					re.ConsumeTo = m.To
763					re.ConsumeNonce = m.Nonce
764					re.ConsumeBy = m.ID
765				}
766				entries = append(entries, re)
767			}
768		}
769		if state.now > 0 {
770			entries = append(entries, &logEntry{T: kindAdvance, Now: state.now})
771		}
772	
773		tmp := filepath.Join(s.dir, logName+".compact")
774		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
775		if err != nil {
776			return err
777		}
778		abort := func(err error) error {
779			f.Close()
780			os.Remove(tmp)
781			return err
782		}
783		if _, err := f.WriteString(logMagic); err != nil {
784			return abort(err)
785		}
786		for _, e := range entries {
787			body, err := json.Marshal(e)
788			if err != nil {
789				return abort(err)
790			}
791			if _, err := f.Write(encodeFrame(body)); err != nil {
792				return abort(err)
793			}
794		}
795		if err := f.Sync(); err != nil {
796			return abort(err)
797		}
798		if err := f.Close(); err != nil {
799			os.Remove(tmp)
800			return err
801		}
802		if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
803			os.Remove(tmp)
804			return err
805		}
806		if err := syncDir(s.dir); err != nil {
807			return err
808		}
809		nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
810		if err != nil {
811			return err
812		}
813		if _, err := nf.Seek(0, io.SeekEnd); err != nil {
814			nf.Close()
815			return err
816		}
817		s.f.Close()
818		s.f = nf
819		if info, err := nf.Stat(); err == nil {
820			s.size = info.Size()
821		}
822		return nil
823	}
824	
825	// syncDir fsyncs a directory so that file creation and rename survive a crash.
826	func syncDir(dir string) error {
827		d, err := os.Open(dir)
828		if err != nil {
829			return fmt.Errorf("open directory for sync: %w", err)
830		}
831		defer d.Close()
832		if err := d.Sync(); err != nil {
833			return fmt.Errorf("sync directory %s: %w", dir, err)
834		}
835		return nil
836	}
